import { type MeQueryResult, useMeQuery } from '@/generated/graphql'

export type Me = NonNullable<MeQueryResult['data']>['me']

interface UseMeState {
	me: Me | null
	loading: boolean
	previousData: Me | null
	refetch: () => Promise<void>
}

export const useMe = (): UseMeState => {
	const { loading, data, refetch, previousData } = useMeQuery({
		fetchPolicy: 'cache-first',
		nextFetchPolicy: 'cache-only'
	})

	return {
		me: data?.me ?? null,
		previousData: previousData?.me ?? null,
		loading,
		refetch: async () => {
			await refetch()
		}
	}
}
